PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "company_name" (company_id TEXT,  company_name TEXT,  company_order TEXT);
CREATE TABLE IF NOT EXISTS "brand" (brand_id TEXT,  generic_id TEXT,  company_id TEXT,  brand_name TEXT,  form TEXT,  strength TEXT,  price TEXT,  packsize TEXT);
CREATE TABLE IF NOT EXISTS "generic" (generic_id TEXT,  generic_name TEXT,  precaution TEXT,  indication TEXT,  contra_indication TEXT,  dose TEXT,  side_effect TEXT,  pregnancy_category_id TEXT, "mode_of_action" TEXT, "interaction" TEXT);
CREATE TABLE IF NOT EXISTS "indication" (indication_id TEXT,  indication_name TEXT);
CREATE TABLE IF NOT EXISTS "indication_generic_index" (generic_id TEXT,  indication_id TEXT);
CREATE TABLE IF NOT EXISTS "pregnancy_category" (pregnancy_id TEXT,  pregnancy_name TEXT,  pregnancy_description TEXT);
CREATE TABLE IF NOT EXISTS "systemic" (systemic_id TEXT,  systemic_name TEXT,  systemic_parent_id TEXT);
CREATE TABLE IF NOT EXISTS "therapitic" (therapitic_id TEXT,  therapitic_name TEXT,  therapitic_systemic_class_id TEXT);
CREATE TABLE IF NOT EXISTS "therapitic_generic" (generic_id TEXT,  therapitic_id TEXT);
COMMIT;
